{
    int i, n, r;
    for ( i = 0; i < 256; i++ )
    {
        if ( i % 8 == 0 )
            printf( "\n" );
        for ( r = n = 0; n < 8; n++ )
            r |= ((i & (1 << n)) << n);
        printf( "0x%04x, ", r );
    }
}

