void Kit_PermCreateP()
{
    int i, s1, s2, r;
    for ( i = 0; i < 256; i++ )
    {
        if ( i % 16 == 0 )
            printf( "\n" );
        s1 = i & 0x0A;
        s2 = i & 0x50;
        r = i ^ s1 ^ s2 ^ (s1 << 3) ^ (s2 >> 3);
        assert( r < 256 );
        printf( "0x%02x, ", r );
    }
}

