static inline void Kit_PermCycleOne( shot * s, byte * b, int v )
{
    int i, n = (1 << (v-3));
    assert( v > 2 && v < 16 );
    for ( i = 0; i < n; i++ )
        s[i] = S[b[i]] | (S[b[i+n]] << 1);
}

