static inline void Kit_PermCycleMany( shot * s, byte * b, int V, int v )
{
    int i, n = (1 << (V - 1 - v)), m = (1 << (v-2));
    assert( v > 2 && v < V );
    for ( i = 0; i < n; i++, s += (m >> 1), b += m )
        Kit_PermCycleOne( s, b, v );   
}

