void Kit_PermCompute( word * o, word * i, int V )
{
    word * t;
    int v, n = (1 << (V-3));
    assert( V >= 6 && V <= 16 );
    for ( v = 0; v < n; v++ )
        ((byte *)i)[v] = P[((byte *)i)[v]];
    for ( v = 3; v < V; v++ )
    {
        Kit_PermCycleMany( (shot *)o, (byte *)i, V, v );
        t = i; i = o; o = t;
    }
    if ( V & 1 )
    {
        n = (1 << (V-6));
        for ( v = 0; v < n; v++ )
            o[v] = i[v];
    }
}

