word M ( word f1, word f2, int n)
{
    word temp = 0;
    word a = 1;
    int i;
    for(  i = 0; i < n; i++)
        temp = temp + (((f1>>i)&a) << (2*i) ) + (((f2>>i)&a) << (2*i+1));
    return temp;
}

